package io.metersphere.agent.controller;
import io.metersphere.agent.dto.*;import io.metersphere.agent.service.AgentBusinessFlowService;import io.metersphere.sdk.constants.PermissionConstants;import jakarta.annotation.Resource;import jakarta.validation.Valid;import org.apache.shiro.authz.annotation.RequiresPermissions;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping({"/ai/business-flows","/api/ai/business-flows"}) public class AgentBusinessFlowController {@Resource private AgentBusinessFlowService service;@GetMapping @RequiresPermissions(PermissionConstants.AI_EXECUTION_READ)public List<AgentBusinessFlowDTO> list(@RequestParam String projectId){return service.list(projectId);}@GetMapping("/{id}")@RequiresPermissions(PermissionConstants.AI_EXECUTION_READ)public AgentBusinessFlowDTO get(@PathVariable String id){return service.get(id);}@PostMapping @RequiresPermissions(PermissionConstants.AI_EXECUTION_RUN)public AgentBusinessFlowDTO create(@RequestBody@Valid AgentBusinessFlowRequest r){return service.create(r);}@PutMapping("/{id}")@RequiresPermissions(PermissionConstants.AI_EXECUTION_RUN)public AgentBusinessFlowDTO update(@PathVariable String id,@RequestBody@Valid AgentBusinessFlowRequest r){return service.update(id,r);}}
